      model.nodes.forEach((node2) => {
        nodes.push([
          node2.id,
          Math.round(node2.x),
          Math.round(node2.y),
          node2.init,
          encodeURIComponent(encodeURIComponent(node2.label)),
          encodeURIComponent(encodeURIComponent(node2.color)),
          Math.round(node2.w),
          Math.round(node2.h)
        ]);
      });
      data.push(nodes);
      let edges = [];
      model.edges.forEach((edge) => {
        edges.push([
          edge.from.id,
          edge.to.id,
          Math.round(edge.arc),
          edge.strength,
          Math.round(edge.rotation),
          edge.thickness,
          encodeURIComponent(encodeURIComponent(edge.color)),
          edge.delay
        ]);
      });
      data.push(edges);
      let labels = [];
      model.labels.forEach((label) => {
        labels.push([
          Math.round(label.x),
          Math.round(label.y),
          encodeURIComponent(encodeURIComponent(label.text)),
          encodeURIComponent(encodeURIComponent(label.color))
        ]);
      });
      data.push(labels);
      data.push(model.nodeUID);
