    addList("Feedback loops", loops.map((loop) => ({ label: `${loop.kind === "reinforcing" ? "R \xB7 reinforcing" : loop.kind === "balancing" ? "B \xB7 balancing" : "? \xB7 sign unknown"} \xB7 ${loop.label}` })));
